     1→# ABOUTME: Earley parser implementation with Leo optimization for Chalk
     2→# ABOUTME: Provides EarleyItem, LeoItem, EarleyChart, and Parser classes
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Semiring::Boolean;
     7→
     8→class Chalk::EarleyItem {
     9→    use overload '""' => 'key';
    10→
    11→    field $start_pos :param :reader;
    12→    field $rule      :param :reader;
    13→    field $dot_pos   :param :reader;
    14→    field $end_pos   :param :reader;
    15→    field $rule_id = $rule->id;
    16→    field @rhs     = $rule->rhs->@*;
    17→    field $complete    :reader = $dot_pos >= scalar(@rhs);
    18→    field $next_symbol :reader = $complete ? '' : $rhs[$dot_pos];
    19→    field $key = "Earley|$start_pos|$rule_id|$dot_pos|$end_pos";
    20→
    21→    method advance_dot() {
    22→        Chalk::EarleyItem->new(
    23→            start_pos => $start_pos,
    24→            rule      => $rule,
    25→            dot_pos   => $dot_pos + 1,
    26→            end_pos   => $end_pos,
    27→        );
    28→    }
    29→
    30→    method key(@args) { $key }
    31→}
    32→
    33→# Leo Items: Limited optimization for right-recursive grammar patterns
    34→#
    35→# This is a LIMITED implementation of Joop Leo's optimization (1991) for right-recursive
    36→# grammars.  It creates "Leo items" only in DETERMINISTIC cases where:
    37→# 1. Exactly one Earley item is waiting for the completed symbol
    38→# 2. The waiting item will be complete after this one reduction
    39→# 3. The rule is right-recursive (LHS appears as last RHS symbol)
    40→#
    41→# Why limited? Full Leo would create items even with multiple waiting items and maintain
    42→# a hash lookup by (position, symbol). Our grammar has 41 right-recursive rules, but
    43→# performance testing shows grammar complexity (960+ rules) is the main bottleneck,
    44→# not right-recursion specifically. This limited implementation provides O(n) behavior
    45→# for simple right-recursive chains (ArrowChain, StatementList) without the complexity
    46→# of full Leo.
    47→#
    48→# See t/optimization/test-leo-items.t for verification tests.
    49→# See issue #10 for detailed analysis and rationale.
    50→class Chalk::LeoItem {
    51→    use overload '""' => 'key';
    52→
    53→    field $symbol    :param :reader;
    54→    field $start_pos :param :reader;
    55→    field $end_pos   :param :reader;
    56→    field $top_item  :param :reader;
    57→    field $rule      :reader = $top_item->rule;
    58→
    59→    method complete()    { 1 }
    60→    method next_symbol() { }
    61→
    62→    method key(@args) {
    63→        return "LEO:$symbol|$start_pos|$end_pos";
    64→    }
    65→
    66→}
    67→
    68→class Chalk::EarleyChart {
    69→    field $semiring :param;
    70→    field %chart;
    71→    field @by_end_pos;
    72→    field %predicted;    # Track what we've predicted at each position
    73→    field %completed;    # Track what we've completed
    74→    field %waiting_for;  # Index: waiting_for{symbol}{pos} = [items waiting for symbol at pos]
    75→    field %leo_waiting_for;  # Index: leo_waiting_for{symbol}{pos} = [Leo items waiting for symbol at pos]
    76→
    77→    method add_item($earley_item) {
    78→        $chart{ $earley_item->key } = $earley_item;
    79→    }
    80→
    81→    method get_element($key) { $chart{$key} }
    82→
    83→    method add_element( $item, $element ) {
    84→        my $key     = $item->key;
    85→        my $current = $self->get_element($key);
    86→        $chart{$key} = $current ? $current + $element : $element;
    87→
    88→        my $end_pos = $item->end_pos;
    89→        push( $by_end_pos[$end_pos]->@*, $item );
    90→
    91→        # Index by what they're waiting for
    92→        if ($item isa Chalk::LeoItem) {
    93→            # Leo items are indexed by their symbol and end position
    94→            my $symbol = $item->symbol;
    95→            my $leo_end_pos = $item->end_pos;
    96→            $leo_waiting_for{$symbol} //= {};
    97→            my $leo_by_symbol = $leo_waiting_for{$symbol};
    98→            $leo_by_symbol->{$leo_end_pos} //= [];
    99→            my $leo_list = $leo_by_symbol->{$leo_end_pos};
   100→            push( $leo_list->@*, $item );
   101→        }
   102→        elsif (!$item->complete) {
   103→            # Regular items indexed by next_symbol
   104→            my $next_sym = $item->next_symbol;
   105→            if ($next_sym) {
   106→                my $waiting_end_pos = $item->end_pos;
   107→                $waiting_for{$next_sym} //= {};
   108→                my $waiting_by_sym = $waiting_for{$next_sym};
   109→                $waiting_by_sym->{$waiting_end_pos} //= [];
   110→                my $waiting_list = $waiting_by_sym->{$waiting_end_pos};
   111→                push( $waiting_list->@*, $item );
   112→            }
   113→        }
   114→
   115→        return $chart{$key};
   116→    }
   117→
   118→    method items_ending_at($end_pos) {
   119→        return $by_end_pos[$end_pos]->@* if $by_end_pos[$end_pos];
   120→        return;
   121→    }
   122→
   123→    method items_waiting_for($symbol, $pos) {
   124→        my $by_symbol = $waiting_for{$symbol};
   125→        if ($by_symbol && exists($by_symbol->{$pos})) {
   126→            return $by_symbol->{$pos}->@*;
   127→        }
   128→        return;
   129→    }
   130→
   131→    method leo_items_waiting_for($symbol, $pos) {
   132→        my $by_symbol = $leo_waiting_for{$symbol};
   133→        if ($by_symbol && exists($by_symbol->{$pos})) {
   134→            return $by_symbol->{$pos}->@*;
   135→        }
   136→        return;
   137→    }
   138→
   139→    method has_item($item) {
   140→        return exists( $chart{$item} );
   141→    }
   142→
   143→    method has_predicted( $nonterminal, $pos, $rule_id ) {
   144→        return exists( $predicted{"$nonterminal|$pos|$rule_id"} );
   145→    }
   146→
   147→    method mark_predicted( $nonterminal, $pos, $rule_id ) {
   148→        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
   149→    }
   150→
   151→    method has_completed($item) {
   152→        return exists( $completed{$item} );
   153→    }
   154→
   155→    method mark_completed($item) {
   156→        $completed{$item} = 1;
   157→    }
   158→
   159→    method goal_value( $start_symbol, $n ) {
   160→
   161→        # Find all complete items that span [0,n] with LHS = start_symbol
   162→        my $result = $semiring->add_id;
   163→
   164→        my @items = $self->items_ending_at($n);
   165→
   166→        for my $item (@items) {
   167→            next unless $item->complete;
   168→            next unless $item->start_pos == 0;
   169→            next unless $item->rule->lhs eq $start_symbol;
   170→
   171→            my $element = $self->get_element($item);
   172→            if ($element) {
   173→                $result = $result + $element;
   174→
   175→                # Early termination for Boolean semiring: we only need to know
   176→                # IF a parse exists, not enumerate ALL parses. This prevents
   177→                # memory exhaustion when parsing highly ambiguous inputs like
   178→                # the grammar file itself (which has exponentially many parses).
   179→                # For other semirings (like Semantic), we need to accumulate ALL
   180→                # parses to get the correct result.
   181→                if ($semiring isa Chalk::Semiring::Boolean && $result != $semiring->add_id) {
   182→                    return $result;
   183→                }
   184→            }
   185→        }
   186→
   187→        # Check if we found any valid parses
   188→        # Return unevaluated result - let caller decide whether to evaluate
   189→        return $result == $semiring->add_id ? undef : $result;
   190→    }
   191→}
   192→
   193→class Chalk::Parser {
   194→    field $semiring :param = Chalk::Semiring::Boolean->new();
   195→    field $grammar :param;
   196→    field $preprocess :param = [];  # Arrayref of preprocessor class names
   197→    field $input_string;  # Store input string for semantic actions
   198→
   199→    method parse_string($input) {
   200→        $input_string = $input;  # Store for semantic actions
   201→        # Apply preprocessors in sequence
   202→        for my $preprocessor_class ($preprocess->@*) {
   203→            next unless defined $preprocessor_class;
   204→
   205→            # Load the preprocessor module
   206→            my $file = $preprocessor_class;
   207→            my $search = '::';
   208→            my $replace = '/';
   209→            my $pos = index($file, $search);
   210→            while ($pos >= 0) {
   211→                substr($file, $pos, length($search), $replace);
   212→                $pos = index($file, $search, $pos + length($replace));
   213→            }
   214→            require "$file.pm";
   215→
   216→            # Apply preprocessing
   217→            my $preprocessor = $preprocessor_class->new(input => $input);
   218→            $preprocessor->transform();
   219→            $input = $preprocessor->output;
   220→        }
   221→
   222→        my $chart = Chalk::EarleyChart->new( semiring => $semiring );
   223→
   224→       # Initialize chart by predicting all rules for start symbol at position 0
   225→        my $start_symbol = $grammar->start_symbol;
   226→        for my $rule ( $grammar->rules_for($start_symbol) ) {
   227→            my $start_item = Chalk::EarleyItem->new(
   228→                start_pos => 0,
   229→                rule      => $rule,
   230→                dot_pos   => 0,
   231→                end_pos   => 0,
   232→            );
   233→
   234→            my $start_element = $semiring->init_element_from_rule($rule, 0, 0);
   235→            $chart->add_element( $start_item, $start_element );
   236→        }
   237→
   238→        # Process positions from 0 to end of string
   239→        my $pos             = 0;
   240→        my $input_length    = length($input);
   241→        my $last_active_pos = 0;
   242→
   243→        # Store input_string for semantic actions
   244→        $input_string = $input;
   245→
   246→        while ( $pos <= $input_length ) {
   247→            my @agenda_before = $chart->items_ending_at($pos);
   248→            $self->process_position_string( $pos, $chart, $input );
   249→
   250→            # Track the last position where we had active items
   251→            if ( @agenda_before > 0 ) {
   252→                $last_active_pos = $pos;
   253→            }
   254→
   255→            ++$pos;
   256→        }
   257→
   258→        my $result =
   259→          $chart->goal_value( $grammar->start_symbol, $input_length );
   260→
   261→        # Show where parsing actually stopped if it failed
   262→        if ( !$result && $last_active_pos < $input_length ) {
   263→            warn(
   264→"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
   265→                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
   266→                  . "%)\n" );
   267→        }
   268→
   269→        return $result;
   270→    }
   271→
   272→    method process_position_string( $pos, $chart, $input_string ) {
   273→        my @agenda = $chart->items_ending_at($pos);
   274→
   275→        my $item;
   276→        while ( $item = shift(@agenda) ) {
   277→            my $element = $chart->get_element($item);
   278→            next unless defined($element);
   279→
   280→            if ( $item->complete ) {
   281→                $self->complete( $item, $element, $chart, \@agenda );
   282→            }
   283→            else {
   284→                my $next_sym = $item->next_symbol;
   285→                if (defined($next_sym)) {
   286→                    if ($grammar->is_nonterminal($next_sym) ) {
   287→                        $self->predict( $item, $next_sym, $chart, \@agenda );
   288→                    }
   289→                    else {
   290→                        # Try to match terminal with lexeme support
   291→                        my $pattern = $item->rule->terminal_to_regex($next_sym);
   292→                        pos($input_string) = $pos;
   293→                        my $match_pattern = qr/\G($pattern)/;
   294→                        if ( $input_string =~ $match_pattern ) {
   295→                            my $match_length = length($1);
   296→                            $self->scan( $item, $element, $chart, $pos,
   297→                                $match_length );
   298→                        }
   299→
   300→                        # Aycock-Horspool optimization for nullable terminals:
   301→                        # If the terminal can match empty string, also advance dot
   302→                        if (ref($next_sym) eq 'Regexp' && "" =~ $next_sym) {
   303→                            my $advanced_item = Chalk::EarleyItem->new(
   304→                                start_pos => $item->start_pos,
   305→                                rule      => $item->rule,
   306→                                dot_pos   => $item->dot_pos + 1,
   307→                                end_pos   => $item->end_pos
   308→                            );
   309→
   310→                            unless ( $chart->has_item($advanced_item) ) {
   311→                                $chart->add_element( $advanced_item, $element );
   312→                                push( @agenda, $advanced_item );
   313→                            }
   314→                        }
   315→                    }
   316→                }
   317→            }
   318→        }
   319→    }
   320→
   321→    method complete( $completed_item, $completed_element, $chart, $agenda ) {
   322→
   323→        # Check if we've already completed this item
   324→        return if $chart->has_completed($completed_item);
   325→        $chart->mark_completed($completed_item);
   326→
   327→        my $lhs = $completed_item->rule->lhs;
   328→
   329→        # For Semantic semiring, evaluate the completed rule
   330→        # NOTE: We evaluate and set the focus, but keep the children so they can
   331→        # be accessed by parent rules during their evaluation
   332→        if ($semiring isa Chalk::Semiring::Semantic) {
   333→            # IMPORTANT: Get the LATEST element from the chart, not the one passed in!
   334→            # The element passed in might be stale if multiply operations happened
   335→            my $latest_element = $chart->get_element($completed_item);
   336→            if ($latest_element) {
   337→                $completed_element = $latest_element;
   338→            }
   339→
   340→            my $ctx = $completed_element->context;
   341→
   342→            # Evaluate the rule's semantic action if it has one
   343→            my $rule = $ctx->rule;
   344→            if ($rule && $rule->can('evaluate')) {
   345→                my $result = $rule->evaluate($ctx);
   346→
   347→                # Set the focus to the evaluated result
   348→                # This maintains the result while preserving children for parent rules
   349→                $ctx = Chalk::EvalContext->new(
   350→                    focus => $result,
   351→                    children => $ctx->children,
   352→                    start_pos => $ctx->start_pos,
   353→                    end_pos => $ctx->end_pos,
   354→                    env => $ctx->env,
   355→                    grammar => $ctx->grammar,
   356→                    rule => $ctx->rule,
   357→                    forest => $ctx->forest
   358→                );
   359→
   360→                # Update the completed element with evaluated context
   361→                $completed_element = Chalk::Semiring::SemanticElement->new(
   362→                    value => 1,
   363→                    context => $ctx
   364→                );
   365→
   366→                # Update the chart with evaluated element
   367→                # The element has both the evaluated focus AND the accumulated children
   368→                $chart->add_element($completed_item, $completed_element);
   369→            }
   370→        }
   371→
   372→        # Use indexed lookups to get items waiting for this symbol
   373→        # This avoids the expensive grep operations with isa checks
   374→        my @waiting_for_lhs = $chart->items_waiting_for($lhs, $completed_item->start_pos);
   375→        my @leo_waiting = $chart->leo_items_waiting_for($lhs, $completed_item->start_pos);
   376→
   377→  # Check for deterministic reduction (only if no Leo items waiting)
   378→  # Leo items are only for deterministic right-recursive chains where:
   379→  # 1. Only one item is waiting for this LHS
   380→  # 2. The waiting item will be complete after this reduction
   381→  # 3. The rule is right-recursive
   382→  #
   383→  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
   384→  # here, but performance testing shows left-recursion is already faster than
   385→  # right-recursion in our Earley implementation, so it's not needed.
   386→        if (   @waiting_for_lhs == 1
   387→            && @leo_waiting == 0
   388→            && $waiting_for_lhs[0]->rule->is_right_recursive
   389→            && $waiting_for_lhs[0]->dot_pos ==
   390→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   391→        {
   392→            my $waiting_item = $waiting_for_lhs[0];
   393→
   394→            # Use completed item's end position
   395→            my $leo = Chalk::LeoItem->new(
   396→                symbol    => $lhs,
   397→                start_pos => $waiting_item->start_pos,
   398→                end_pos   => $completed_item->end_pos,
   399→                top_item  => $waiting_item,
   400→            );
   401→
   402→            my $waiting_element = $chart->get_element($waiting_item);
   403→            next unless $waiting_element;
   404→            my $combined_element = $waiting_element * $completed_element;
   405→            $chart->add_element( $leo, $combined_element );
   406→            push( $agenda->@*, $leo );
   407→            return;    # Skip normal completion
   408→        }
   409→
   410→        # Normal completion for regular items
   411→        for my $waiting_item (@waiting_for_lhs) {
   412→
   413→            my $waiting_element = $chart->get_element($waiting_item);
   414→            next unless $waiting_element;
   415→
   416→            # Semiring multiplication ⊗ combines sequential components
