   893→    method build_use_statement_node($type, $module, $imports) {
   894→        # Create UseStatement node for capturing use statement metadata
   895→        # $type: 'version', 'pragma', 'module', or 'external'
   896→        # $module: module name (e.g., '5.42.0', 'experimental', 'Chalk::IR::Node')
   897→        # $imports: arrayref of imported symbols (empty for full import)
   898→
   899→        my $graph = $self->graph;
   900→        my $current_control = $self->current_control;
   901→
   902→        my $attributes = {
   903→            type => $type,
   904→            module => $module,
   905→            imports => $imports
   906→        };
   907→
   908→        my $node_id = $self->next_node_id();
   909→        my $use_stmt = Chalk::IR::Node->new(
   910→            id => $node_id,
   911→            op => 'UseStatement',
