    45→};
    46→
    47→# Test arithmetic operations
    48→subtest 'Arithmetic node execution' => sub {
    49→    # Create a values map simulating already-computed node values
    50→    my %values = (
    51→        'node_left' => 10,
    52→        'node_right' => 3,
    53→    );
    54→
    55→    # Test Add: 10 + 3 = 13
    56→    my $add = Chalk::IR::Node::Add->new(
    57→        id => 'node_add',
