    59→        left_id => 'node_left',
    60→        right_id => 'node_right',
    61→    );
    62→    my $add_result = $add->execute(\%values);
    63→    is($add_result, 13, 'Add node: 10 + 3 = 13');
    64→
    65→    # Test Subtract: 10 - 3 = 7
    66→    my $sub = Chalk::IR::Node::Subtract->new(
    67→        id => 'node_sub',
    68→        inputs => ['node_ctrl', 'node_left', 'node_right'],
    69→        left_id => 'node_left',
    70→        right_id => 'node_right',
    71→    );
    72→    my $sub_result = $sub->execute(\%values);
    73→    is($sub_result, 7, 'Subtract node: 10 - 3 = 7');
    74→
    75→    # Test Multiply: 10 * 3 = 30
    76→    my $mul = Chalk::IR::Node::Multiply->new(
    77→        id => 'node_mul',
    78→        inputs => ['node_ctrl', 'node_left', 'node_right'],
    79→        left_id => 'node_left',
    80→        right_id => 'node_right',
    81→    );
    82→    my $mul_result = $mul->execute(\%values);
    83→    is($mul_result, 30, 'Multiply node: 10 * 3 = 30');
    84→
    85→    # Test Divide: 10 / 3 = 3.333...
    86→    my $div = Chalk::IR::Node::Divide->new(
    87→        id => 'node_div',
    88→        inputs => ['node_ctrl', 'node_left', 'node_right'],
    89→        left_id => 'node_left',
    90→        right_id => 'node_right',
    91→    );
    92→    my $div_result = $div->execute(\%values);
    93→    cmp_ok($div_result, '==', 10/3, 'Divide node: 10 / 3');
    94→};
    95→
    96→# Test comparison operators
    97→subtest 'Comparison operators execution' => sub {
    98→    my %values = (
    99→        'node_left' => 10,
   100→        'node_right' => 3,
   101→    );
   102→
   103→    # Test GT: 10 > 3 = true (1)
   104→    my $gt = Chalk::IR::Node::GT->new(
   105→        id => 'node_gt',
   106→        inputs => ['node_ctrl', 'node_left', 'node_right'],
   107→        left_id => 'node_left',
   108→        right_id => 'node_right',
   109→    );
   110→    my $gt_result = $gt->execute(\%values);
   111→    is($gt_result, 1, 'GT: 10 > 3 = true');
   112→
   113→    # Test LT: 10 < 3 = false (0)
   114→    my $lt = Chalk::IR::Node::LT->new(
   115→        id => 'node_lt',
   116→        inputs => ['node_ctrl', 'node_left', 'node_right'],
   117→        left_id => 'node_left',
   118→        right_id => 'node_right',
   119→    );
   120→    my $lt_result = $lt->execute(\%values);
   121→    is($lt_result, 0, 'LT: 10 < 3 = false');
   122→
   123→    # Test EQ: 10 == 10 = true
   124→    $values{'node_right'} = 10;
   125→    my $eq = Chalk::IR::Node::EQ->new(
   126→        id => 'node_eq',
   127→        inputs => ['node_ctrl', 'node_left', 'node_right'],
   128→        left_id => 'node_left',
   129→        right_id => 'node_right',
   130→    );
   131→    my $eq_result = $eq->execute(\%values);
   132→    is($eq_result, 1, 'EQ: 10 == 10 = true');
   133→
   134→    # Test NE: 10 != 3 = true
   135→    $values{'node_right'} = 3;
   136→    my $ne = Chalk::IR::Node::NE->new(
   137→        id => 'node_ne',
   138→        inputs => ['node_ctrl', 'node_left', 'node_right'],
   139→        left_id => 'node_left',
   140→        right_id => 'node_right',
   141→    );
   142→    my $ne_result = $ne->execute(\%values);
   143→    is($ne_result, 1, 'NE: 10 != 3 = true');
   144→
   145→    # Test GE: 10 >= 10 = true
   146→    $values{'node_right'} = 10;
   147→    my $ge = Chalk::IR::Node::GE->new(
   148→        id => 'node_ge',
   149→        inputs => ['node_ctrl', 'node_left', 'node_right'],
   150→        left_id => 'node_left',
   151→        right_id => 'node_right',
   152→    );
   153→    my $ge_result = $ge->execute(\%values);
   154→    is($ge_result, 1, 'GE: 10 >= 10 = true');
   155→
   156→    # Test LE: 10 <= 3 = false
   157→    $values{'node_right'} = 3;
   158→    my $le = Chalk::IR::Node::LE->new(
   159→        id => 'node_le',
   160→        inputs => ['node_ctrl', 'node_left', 'node_right'],
   161→        left_id => 'node_left',
   162→        right_id => 'node_right',
   163→    );
   164→    my $le_result = $le->execute(\%values);
   165→    is($le_result, 0, 'LE: 10 <= 3 = false');
   166→};
   167→
   168→# Test unary operators
   169→subtest 'Unary operators execution' => sub {
   170→    # Test Negate: -(-5) = 5
   171→    my %values = ('node_operand' => -5);
   172→    my $negate = Chalk::IR::Node::Negate->new(
   173→        id => 'node_neg',
   174→        inputs => ['node_ctrl', 'node_operand'],
   175→        operand_id => 'node_operand',
   176→    );
   177→    my $result = $negate->execute(\%values);
   178→    is($result, 5, 'Negate: -(-5) = 5');
   179→
   180→    # Test Negate: -(42) = -42
   181→    $values{'node_operand'} = 42;
   182→    my $negate2 = Chalk::IR::Node::Negate->new(
   183→        id => 'node_neg2',
   184→        inputs => ['node_ctrl', 'node_operand'],
   185→        operand_id => 'node_operand',
   186→    );
   187→    my $result2 = $negate2->execute(\%values);
   188→    is($result2, -42, 'Negate: -(42) = -42');
   189→};
   190→
   191→# Test control flow nodes
   192→subtest 'Control flow: If node execution' => sub {
   193→    # If node returns the condition value
   194→    my %values = ('node_cond' => 1);
   195→    my $if = Chalk::IR::Node::If->new(
   196→        id => 'node_if',
   197→        inputs => ['node_ctrl', 'node_cond'],
   198→        condition_id => 'node_cond',
   199→    );
   200→    my $result = $if->execute(\%values);
   201→    is($result, 1, 'If node returns condition value (true)');
