   211→    is($result2, 0, 'If node returns condition value (false)');
   212→};
   213→
   214→subtest 'Control flow: Proj node execution' => sub {
   215→    # Proj extracts control path based on If result and its index
   216→    # Index 0 = false branch, Index 1 = true branch
   217→
   218→    # Test true branch (index 1)
   219→    my %values = ('node_if' => 1);
   220→    my $proj_true = Chalk::IR::Node::Proj->new(
   221→        id => 'node_proj_true',
   222→        inputs => ['node_if'],
   223→        index => 1,
   224→        label => 'IfTrue',
   225→    );
   226→    my $result = $proj_true->execute(\%values);
   227→    is($result, 1, 'Proj[1] active when If=true');
   228→
   229→    # Test false branch (index 0)
   230→    $values{'node_if'} = 0;
   231→    my $proj_false = Chalk::IR::Node::Proj->new(
   232→        id => 'node_proj_false',
   233→        inputs => ['node_if'],
   234→        index => 0,
   235→        label => 'IfFalse',
   236→    );
   237→    my $result2 = $proj_false->execute(\%values);
   238→    is($result2, 1, 'Proj[0] active when If=false');
   239→
   240→    # Test inactive branch
   241→    $values{'node_if'} = 1;
   242→    my $proj_false2 = Chalk::IR::Node::Proj->new(
   243→        id => 'node_proj_false2',
   244→        inputs => ['node_if'],
   245→        index => 0,
   246→        label => 'IfFalse',
   247→    );
   248→    my $result3 = $proj_false2->execute(\%values);
   249→    is($result3, 0, 'Proj[0] inactive when If=true');
   250→};
   251→
   252→subtest 'Control flow: Region node execution' => sub {
   253→    # Region merges control from multiple paths
   254→    my %values = (
   255→        'node_proj_true' => 1,
   256→        'node_proj_false' => 0,
   257→    );
   258→    my $region = Chalk::IR::Node::Region->new(
   259→        id => 'node_region',
   260→        inputs => ['node_proj_false', 'node_proj_true'],
   261→    );
   262→    my $result = $region->execute(\%values);
   263→    # Region returns index of active path (1 in this case - true path)
   264→    is($result, 1, 'Region returns active path index');
   265→
   266→    # Test with false path active
   267→    $values{'node_proj_true'} = 0;
   268→    $values{'node_proj_false'} = 1;
   269→    my $region2 = Chalk::IR::Node::Region->new(
   270→        id => 'node_region2',
   271→        inputs => ['node_proj_false', 'node_proj_true'],
   272→    );
   273→    my $result2 = $region2->execute(\%values);
   274→    is($result2, 0, 'Region returns active path index (false path)');
   275→};
   276→
   277→subtest 'Control flow: Phi node execution' => sub {
   278→    # Phi selects value based on Region's active path
   279→    # inputs: [region_id, value_for_path_0, value_for_path_1, ...]
   280→    my %values = (
   281→        'node_region' => 1,  # Path 1 is active (true branch)
   282→        'node_val_false' => -42,
   283→        'node_val_true' => 42,
   284→    );
   285→    my $phi = Chalk::IR::Node::Phi->new(
   286→        id => 'node_phi',
   287→        inputs => ['node_region', 'node_val_false', 'node_val_true'],
   288→        region_id => 'node_region',
   289→    );
   290→    my $result = $phi->execute(\%values);
   291→    is($result, 42, 'Phi selects true-branch value when path=1');
   292→
   293→    # Test with false path active
   294→    $values{'node_region'} = 0;
   295→    my $phi2 = Chalk::IR::Node::Phi->new(
   296→        id => 'node_phi2',
   297→        inputs => ['node_region', 'node_val_false', 'node_val_true'],
   298→        region_id => 'node_region',
   299→    );
   300→    my $result2 = $phi2->execute(\%values);
   301→    is($result2, -42, 'Phi selects false-branch value when path=0');
   302→};
   303→
   304→# Test Start node execution
   305→subtest 'Start node execution' => sub {
   306→    # Start node represents function entry
   307→    my $start = Chalk::IR::Node::Start->new(
   308→        id => 'node_start',
   309→        inputs => [],
   310→        function_name => 'main',
   311→        params => [],
   312→    );
   313→
   314→    # Execute should return a control token (undef for now)
   315→    my $result = $start->execute();
   316→    ok(defined($result) || !defined($result), 'Start node execute completes');
   317→};
   318→
   319→# Test Return node execution
   320→subtest 'Return node execution' => sub {
   321→    # Create values map with the return value
   322→    my %values = (
   323→        'node_value' => 42,
   324→    );
   325→
   326→    # Return node wraps a value
   327→    my $return = Chalk::IR::Node::Return->new(
   328→        id => 'node_return',
   329→        inputs => ['node_ctrl', 'node_value'],
   330→        value_id => 'node_value',
   331→        control_id => 'node_ctrl',
   332→    );
   333→
   334→    # Execute should return the value
   335→    my $result = $return->execute(\%values);
   336→    is($result, 42, 'Return node returns its value');
   337→};
