   339→# Test graph linearization
   340→subtest 'Simple graph linearization' => sub {
   341→    my $graph = Chalk::IR::Graph->new();
   342→
   343→    # Create a simple graph: Start -> Constant -> Return
   344→    my $start = Chalk::IR::Node::Start->new(
   345→        id => 'node_0',
   346→        inputs => [],
   347→        function_name => 'main',
   348→        params => [],
   349→    );
   350→    $graph->add_node($start);
   351→
   352→    my $constant = Chalk::IR::Node::Constant->new(
   353→        id => 'node_1',
   354→        inputs => ['node_0'],
   355→        value => 42,
   356→        type => 'Int',
   357→    );
   358→    $graph->add_node($constant);
   359→
   360→    my $return = Chalk::IR::Node::Return->new(
   361→        id => 'node_2',
   362→        inputs => ['node_0', 'node_1'],
   363→        value_id => 'node_1',
   364→        control_id => 'node_0',
   365→    );
   366→    $graph->add_node($return);
   367→
   368→    # Linearize the graph
   369→    my @schedule = $graph->linearize();
   370→
   371→    # Verify we have all 3 nodes
   372→    is(scalar(@schedule), 3, 'Linearization includes all 3 nodes');
   373→
   374→    # Verify order: Start must come before Constant and Return
   375→    my %positions;
   376→    for my $i (0..$#schedule) {
   377→        $positions{$schedule[$i]->id} = $i;
   378→    }
   379→
   380→    ok($positions{'node_0'} < $positions{'node_1'}, 'Start before Constant');
   381→    ok($positions{'node_0'} < $positions{'node_2'}, 'Start before Return');
   382→    ok($positions{'node_1'} < $positions{'node_2'}, 'Constant before Return');
   383→};
