    exit 0;
}

# Try to execute
print "\n3. ATTEMPTING EXECUTION...\n";
eval {
    my $interpreter = Chalk::IR::Interpreter->new(graph => $graph);
    my $exec_result = $interpreter->execute();
    print "✓ Execution successful!\n";
    print "   Result: $exec_result\n";
    print "   Expected: 16 (from (3 + 5) * 2)\n";
    if ($exec_result == 16) {
        print "\n🎉 SUCCESS: Full pipeline works!\n";
    } else {
        print "\n⚠ WARNING: Got wrong result\n";
    }
};
if ($@) {
    print "✗ Execution failed: $@\n";
}

print "\n" . "=" x 60 . "\n";
EOF
